composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      MYSQL_ROOT_PASSWORD: {{env.MYSQL_ROOT_PASSWORD}}
      SECRET_KEY_BASE: {{env.SECRET_KEY_BASE}}
    volumes:
      - {{appDataPath}}/data:/foodsoft/storage
    depends_on:
      - {{serviceName}}-mysql
  {{serviceName}}-mysql:
    image: mysql:8
    container_name: {{serviceName}}-mysql
    restart: unless-stopped
    environment:
      MYSQL_DATABASE: foodsoft
      MYSQL_USER: foodsoft
      MYSQL_PASSWORD: {{env.MYSQL_ROOT_PASSWORD}}
      MYSQL_ROOT_PASSWORD: {{env.MYSQL_ROOT_PASSWORD}}
    volumes:
      - {{appDataPath}}/mysql:/var/lib/mysql
